		void read_particleemitterdef(zone_reader& reader, ParticleEmitterDef& data)
		{
			if (const auto items_0 = reader.read_array(data.stateDefs, 15, data.numStates))
			{
				if (data.numStates != 0)
				{
					for (std::size_t i1 = 0; i1 < data.numStates; i1++)
					{
						read_particlestatedef(reader, items_0[i1]);
					}
				}
			}
			read_particlecurvedef(reader, data.fadeCurveDef);
		}

		void read_particlesystemdef(zone_reader& reader, ParticleSystemDef& data)
		{
			reader.begin_asset();
			reader.push_stream(5);
			reader.read_string(data.name);
			if (const auto items_3 = reader.read_array(data.emitterDefs, 15, data.numEmitters))
			{
				if (data.numEmitters != 0)
				{
					for (std::size_t i1 = 0; i1 < data.numEmitters; i1++)
					{
						read_particleemitterdef(reader, items_3[i1]);
					}
				}
			}
			reader.read_array(data.scriptedInputNodeDefs, 15, data.numScriptedInputNodes);
			reader.pop_stream();
			reader.end_asset();
		}

